package dev.astralreach.hytale;
import com.hypixel.hytale.codec.builder.BuilderCodec;import com.hypixel.hytale.component.CommandBuffer;import com.hypixel.hytale.protocol.InteractionType;import com.hypixel.hytale.server.core.entity.InteractionContext;import com.hypixel.hytale.server.core.inventory.ItemStack;import com.hypixel.hytale.server.core.modules.interaction.interaction.CooldownHandler;import com.hypixel.hytale.server.core.modules.interaction.interaction.config.client.SimpleBlockInteraction;import com.hypixel.hytale.server.core.universe.PlayerRef;import com.hypixel.hytale.server.core.universe.world.World;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;import org.joml.Vector3i;
public final class FieldBlockInteraction extends SimpleBlockInteraction{
 public static final BuilderCodec<FieldBlockInteraction>CODEC=BuilderCodec.builder(FieldBlockInteraction.class,FieldBlockInteraction::new,SimpleBlockInteraction.CODEC).build();
 @Override protected void interactWithBlock(World w,CommandBuffer<EntityStore>b,InteractionType t,InteractionContext c,ItemStack held,Vector3i at,CooldownHandler cooldown){var r=c.getEntity();var p=b.getComponent(r,PlayerRef.getComponentType());if(p!=null)w.execute(()->{if(!r.isValid()||r.getStore().getExternalData().getWorld()!=w)return;var s=r.getStore();var cell=new RocketRegistry.Cell(at.x,at.y,at.z);var root=NativeBlocks.root(w,cell);if(root!=null)cell=root;if(!RocketService.near(s,r,cell))return;String id=NativeBlocks.base(NativeBlocks.get(w,cell));FieldPage.open(s,r,p,cell,!id.equals("AR_RescueBeacon"));});}
 @Override protected void simulateInteractWithBlock(InteractionType t,InteractionContext c,ItemStack held,World w,Vector3i at){}
}
